import type { Metadata } from 'next';
import Image from 'next/image';
import Link from 'next/link';
import { ArrowRight, CheckCircle2, Compass } from 'lucide-react';
import { guides } from '../../lib/guides';

export const metadata:Metadata={title:'Safari Planning Guides',description:'Practical East Africa safari planning guides covering costs, seasons, Kenya and Tanzania, family and honeymoon travel, migration timing and safari-beach combinations.',alternates:{canonical:'/guides'}};
export default function GuidesPage(){return <div className="max-w-7xl mx-auto px-4 sm:px-8 py-10 sm:py-14 space-y-10"><header className="max-w-3xl space-y-4"><span className="inline-flex items-center gap-2 text-xs font-extrabold uppercase tracking-widest text-brand-soft"><Compass className="w-4 h-4"/>Plan with confidence</span><h1 className="font-serif-luxury text-4xl sm:text-6xl font-bold text-white">Useful answers before you choose a safari.</h1><p className="text-lg text-on-shell-muted">Guides written around the questions travelers ask while comparing destinations, prices and routes.</p></header><div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">{guides.map(guide=><Link key={guide.slug} href={`/guides/${guide.slug}`} className="group overflow-hidden rounded-2xl bg-white border border-border-strong hover:border-brand transition text-ink"><div className="aspect-[16/10] overflow-hidden relative"><Image src={guide.image} alt="" fill className="object-cover group-hover:scale-[1.03] transition-transform duration-500" sizes="(max-width:768px) 100vw, 33vw"/></div><div className="p-6"><div className="flex items-center gap-2 text-xs font-bold text-brand-deep"><CheckCircle2 className="w-4 h-4"/>Planning guide</div><h2 className="font-serif-luxury text-2xl font-bold text-ink-strong mt-2">{guide.title}</h2><p className="text-sm text-ink-muted mt-2 leading-relaxed">{guide.description}</p><span className="mt-4 inline-flex items-center gap-1 text-sm font-bold text-brand-deep">Read guide <ArrowRight className="w-4 h-4"/></span></div></Link>)}</div></div>}
